public static class CyberOrbFinalState {
 const string Root="Assets/PixelFX/CyberOrb";
 static object SystemInfoOf(ParticleSystem p){var streams=new List<ParticleSystemVertexStream>();var r=p.GetComponent<ParticleSystemRenderer>();r.GetActiveVertexStreams(streams);return new{name=p.name,loop=p.main.loop,duration=p.main.duration,lifeMin=p.main.startLifetime.constantMin,lifeMax=p.main.startLifetime.constantMax,space=p.main.simulationSpace.ToString(),seed=p.randomSeed,autoSeed=p.useAutoRandomSeed,emission=p.emission.enabled,awake=p.main.playOnAwake,lights=p.lights.enabled,sheet=p.textureSheetAnimation.enabled,max=p.main.maxParticles,renderer=r.renderMode.ToString(),alignment=r.alignment.ToString(),material=r.sharedMaterial==null?null:AssetDatabase.GetAssetPath(r.sharedMaterial),streams=streams.Select(x=>x.ToString()).ToArray(),subemitters=Enumerable.Range(0,p.subEmitters.subEmittersCount).Select(i=>new{type=p.subEmitters.GetSubEmitterType(i).ToString(),name=p.subEmitters.GetSubEmitterSystem(i).name,probability=p.subEmitters.GetSubEmitterEmitProbability(i)}).ToArray()};}
 static object Mods(GameObject g)=> (PrefabUtility.GetPropertyModifications(g)??new PropertyModification[0]).Select(m=>{string guid;long id;AssetDatabase.TryGetGUIDAndLocalFileIdentifier(m.target,out guid,out id);return new{target=m.target==null?null:m.target.name,guid,id=id.ToString(),path=m.propertyPath,value=m.value,obj=m.objectReference==null?null:m.objectReference.name};}).ToArray();
 public static string Run(){
