  var project=Directory.GetParent(Application.dataPath).FullName;var output=Path.Combine(project,"VFXWork/Previews/CyberOrb/V3.2");var roots=s.GetRootGameObjects();var baseline=JObject.Parse(File.ReadAllText(Path.Combine(output,"Before.json")));var cam=Camera.main;
  bool cameraPreserved=cam!=null&&EditorJsonUtility.ToJson(cam)==baseline["cameras"][0]["json"].Value<string>()&&cam.transform.position.ToString()==baseline["roots"][0]["pos"].Value<string>()&&cam.transform.rotation.ToString()==baseline["roots"][0]["rot"].Value<string>();
  var shader=AssetDatabase.LoadAssetAtPath<Shader>(Root+"/Shaders/CyberOrbNative.shader");var errors=ShaderUtil.GetShaderMessages(shader).Where(m=>m.severity==UnityEditor.Rendering.ShaderCompilerMessageSeverity.Error).Select(m=>m.message).ToArray();
