  var report=new{success=nativeOnly&&cameraPreserved&&cleanRoots&&errors.Length==0,dataPath=Application.dataPath,product=Application.productName,scene=s.path,dirty=s.isDirty,playing=Application.isPlaying,paused=EditorApplication.isPaused,background=Application.runInBackground,timeScale=Time.timeScale,cameraPreserved,cleanRoots,nativeOnly,prefabs,roots=roots.Select(g=>new{g.name,active=g.activeSelf,position=g.transform.position.ToString(),rotation=g.transform.eulerAngles.ToString(),scale=g.transform.localScale.ToString(),components=g.GetComponentsInChildren<Component>(true).Select(c=>c==null?"MISSING":c.GetType().Name).Distinct().ToArray(),systems=g.GetComponentsInChildren<ParticleSystem>(true).Select(SystemInfoOf).ToArray()}).ToArray(),instances=demo==null?null:Enumerable.Range(0,demo.transform.childCount).Select(i=>{var g=demo.transform.GetChild(i).gameObject;return new{g.name,position=g.transform.localPosition.ToString(),scale=g.transform.localScale.ToString(),modifications=Mods(g)};}).ToArray(),shaderSupported=shader.isSupported,shaderErrors=errors,tailLengthMax=2.8,materials=AssetDatabase.FindAssets("t:Material",new[]{Root}).Select(id=>AssetDatabase.GUIDToAssetPath(id)).ToArray()};
  File.WriteAllText(Path.Combine(output,"FinalState.json"),JsonConvert.SerializeObject(report,Formatting.Indented));Selection.activeGameObject=demo;return JsonConvert.SerializeObject(new{report.success,report.scene,report.dirty,report.cameraPreserved,report.nativeOnly,report.shaderErrors,roots=roots.Select(g=>g.name)});
